#include "Rendering/Backend/NativeUIRecorder.h"
#include "Rendering/Backend/NativeWorldDrawGeometry.h"
#include <iostream>
#include <cmath>
using namespace rendering;
using namespace rendering::ui;
namespace {
unsigned checks=0;
void Check(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}
template<class F>void Reject(F f,const char* message){bool bad=false;try{f();}catch(const std::exception&){bad=true;}Check(bad,message);}
std::shared_ptr<ScreenTexture> Image(unsigned generation=0){auto p=std::make_shared<ScreenTexture>();p->width=p->height=1;p->bytesPerRow=4;p->bytes={128,64,32,192};p->generation=generation;return p;}
std::shared_ptr<NativeUITextureBinding> Binding(std::shared_ptr<const ScreenTexture> image){auto b=std::make_shared<NativeUITextureBinding>();b->current=image;b->sampler={ScreenFilter::Nearest,ScreenWrap::Repeat,ScreenWrap::Repeat};return b;}
void Triangle(NativeUIRecorder& r){r.Begin(ScreenPrimitive::Triangles);r.Vertex(1,1);r.Vertex(7,1);r.Vertex(1,7);r.End();}
void Quad(ScreenDrawList& r){r.BeginQuads();r.Vertex(0,0);r.Vertex(8,0);r.Vertex(8,8);r.Vertex(0,8);r.End();}
void StateAndLists()
{
 NativeUIRecorder r;auto a=Binding(Image()),b=Binding(Image(1)),c=Binding(Image(2));r.BeginFrame(8,8);r.BeginScreenStage();r.SetTextureResource(a);r.SetTextureResource(b,1);r.TexCoord(.1f,.2f);r.MultiTexCoord(1,.7f,.8f);Triangle(r);
 r.SetTextureEnabled(false,1);Triangle(r);r.SetTextureEnabled(true,1);Triangle(r);
 auto frame=r.EndFrame();auto command=frame.drawList->Commands();Check(command.size()==3,"Both texture enables retain ordinary draws");Check(command[0].state.texture==a->current&&command[0].state.secondary.texture==b->current,"Independent primary and secondary names");Check(!command[1].state.secondary.texture&&command[1].state.texture==a->current,"Disable secondary alone");Check(command[2].state.secondary.texture==b->current,"Enable remembers secondary bound name");
 for(const auto& uv:frame.drawList->TexCoords())Check(uv==ScreenTexCoord{.1f,.2f,.7f,.8f},"Declared independent UV0/UV1 byte fields");
 r.BeginFrame(8,8);r.BeginScreenStage();r.SetTextureResource(a);r.SetTextureResource(b,1);r.TexCoord(.2f,.3f);r.MultiTexCoord(1,.4f,.5f);r.PushAttrib(Current);r.MultiTexCoord(1,.6f,.7f);r.PopAttrib();Check(r.CurrentState().texCoord==ScreenTexCoord{.2f,.3f,.4f,.5f},"CURRENT restores both independent coordinates");
 r.BeginList();r.MultiTexCoord(1,.8f,.9f);Triangle(r);auto list=r.EndList();Check(r.CurrentState().texCoord==ScreenTexCoord{.2f,.3f,.4f,.5f},"Compilation cannot change caller current coordinates");auto oldA=a->current,oldB=b->current;a->current=Image(3);b->current=Image(4);b->sampler.filter=ScreenFilter::Linear;r.CallList(list);frame=r.EndFrame();Check(frame.drawList->Commands()[0].state.texture==a->current&&frame.drawList->Commands()[0].state.secondary.texture==b->current,"List inherits and resolves latest both-unit image storage");Check(frame.drawList->Commands()[0].state.secondary.sampler.filter==ScreenFilter::Linear,"List resolves latest secondary object sampler");for(const auto& uv:frame.drawList->TexCoords())Check(uv==ScreenTexCoord{.2f,.3f,.8f,.9f},"List changes only declared unit1 coordinate");Check(oldA->generation==0&&oldB->generation==1,"Old owned immutable generations survive changes");
 r.BeginFrame(8,8);r.BeginScreenStage();r.SetTextureResource(a);r.SetTextureResource(b,1);auto before=b->sampler;r.PushAttrib(Texture);r.SetTextureResource(c,1);b->sampler.filter=ScreenFilter::Nearest;auto updated=Image(5);b->current=updated;r.MultiTexCoord(1,.6f,.5f);r.PopAttrib();Triangle(r);frame=r.EndFrame();Check(frame.drawList->Commands()[0].state.secondary.texture==updated,"Texture pop restores binding and latest generation");Check(b->sampler==before,"Texture pop restores original secondary object parameters");Check(frame.drawList->TexCoords()[0][2]==.6f,"TEXTURE does not restore CURRENT coordinates");
 r.BeginFrame(8,8);r.BeginScreenStage();r.SetTextureResource(a);r.SetTextureResource(b,1);r.SetTextureEnabled(false);r.PushAttrib(Enable);r.SetTextureEnabled(true);r.SetTextureEnabled(false,1);b->sampler.wrapS=ScreenWrap::ClampEdge;r.PopAttrib();Triangle(r);frame=r.EndFrame();Check(!frame.drawList->Commands()[0].state.texture&&frame.drawList->Commands()[0].state.secondary.texture==b->current,"ENABLE restores both enables independently");Check(b->sampler.wrapS==ScreenWrap::ClampEdge,"ENABLE does not roll back object parameters");
 r.BeginFrame(8,8);r.BeginScreenStage();r.SetTextureResource(b,1);r.ResetDrawingState();Triangle(r);frame=r.EndFrame();Check(frame.drawList->Commands()[0].state.secondary.texture==b->current,"Original ResetGLState only disables active texture0");
}
void FeedbackAndRollback()
{
 NativeUIRecorder r;r.BeginFrame(8,8);r.BeginScreenStage();auto target=MakeRenderTargetTexture(8,8,"actual target");target->generation=1;r.BeginTarget(target);Reject([&]{r.SetTexture(target,{},1);},"Secondary cannot sample active self target");r.ClearTarget(ScreenColor{0,0,0,0});r.EndTarget();r.EndFrame();r.RetireCompletedFrame();
 auto a=Binding(Image()),b=Binding(Image()),dead=Binding(Image());r.BeginFrame(8,8);r.BeginScreenStage();r.SetTextureResource(a);r.SetTextureResource(b,1);r.PushAttrib(Texture);r.BeginList();r.PopAttrib();r.SetTextureResource(dead,1);auto list=r.EndList();a->sampler.filter=b->sampler.filter=ScreenFilter::Linear;dead->current.reset();Reject([&]{r.CallList(list);},"Deleted second binding aborts replay");Check(a->sampler.filter==ScreenFilter::Linear&&b->sampler.filter==ScreenFilter::Linear,"Replay failure undoes both texture-object sampler restorations");r.PopAttrib();Triangle(r);auto frame=r.EndFrame();Check(frame.drawList->Commands()[0].state.texture==a->current&&frame.drawList->Commands()[0].state.secondary.texture==b->current,"Replay failure restores both original binding identities");
}
void DependencyAndGeometry()
{
 auto a=MakeRenderTargetTexture(8,8,"producer"),b=MakeRenderTargetTexture(8,8,"consumer");a->generation=b->generation=1;auto first=std::make_shared<ScreenDrawList>();Quad(*first);auto second=std::make_shared<ScreenDrawList>();second->SetSecondaryTexture({a,ScreenUVMode::Normalized,{}});Quad(*second);std::array<ScreenRenderTargetPass,2> passes{{{b,{},second,ScreenTargetLoad::Clear,ScreenTargetStore::Store,{0,0,0,0},8,8},{a,{},first,ScreenTargetLoad::Clear,ScreenTargetStore::Store,{0,0,0,0},8,8}}};ScreenFrameView view{nullptr,8,8,{},passes};Check(OrderScreenRenderTargetPasses(view)==std::vector<std::size_t>{1,0},"Secondary-only RTT dependency orders original producer first");passes[1].store=ScreenTargetStore::DontCare;Reject([&]{OrderScreenRenderTargetPasses(view);},"Discarded target sampled on secondary is invalid");passes[1].store=ScreenTargetStore::Store;second->ClearGeometry();second->SetSecondaryTexture({b,ScreenUVMode::Normalized,{}});Quad(*second);Reject([&]{OrderScreenRenderTargetPasses(view);},"Secondary-only RTT self-feedback cannot hide behind solid primary");
 NativeWorldDrawCommand line;line.primitive=NativeDrawPrimitive::Lines;line.sourcePrimitive=NativeDrawPrimitive::Lines;line.indices={0,1};line.vertices={{{-2,0,0,1},{1,1,1,1},{0,0,10,20}},{{.5f,0,0,1},{1,1,1,1},{1,1,20,40}}};auto mesh=BuildNativeWorldDrawGeometry(line,{0,0,64,64},64,64);Check(!mesh.vertices.empty(),"Original clipped line creates actual geometry");for(const auto& v:mesh.vertices){Check(std::abs(v.uv[2]-(10+10*v.uv[0]))<1e-5f&&std::abs(v.uv[3]-(20+20*v.uv[0]))<1e-5f,"Clipped line pixel interpolation preserves both independent secondary components");}
 NativeWorldDrawCommand polygon;polygon.primitive=NativeDrawPrimitive::Triangles;polygon.sourcePrimitive=NativeDrawPrimitive::Triangles;polygon.indices={0,1,2};polygon.vertices={line.vertices[0],line.vertices[1],{{.5f,.5f,0,1},{1,1,1,1},{1,1,20,40}}};polygon.world.frontPolygonMode=polygon.world.backPolygonMode=NativePolygonMode::Point;auto points=BuildNativeWorldDrawGeometry(polygon,{0,0,64,64},64,64);bool found=false;for(const auto& v:points.vertices)if(std::abs(v.uv[0]-.4f)<1e-5f){found=true;Check(std::abs(v.uv[2]-14)<1e-5f&&std::abs(v.uv[3]-28)<1e-5f,"Original polygon clip intersection preserves both secondary components");}Check(found,"Independent homogeneous clip intersection is present");Check(sizeof(NativeWorldDrawVertex)==48&&offsetof(NativeWorldDrawVertex,uv)==32,"Actual world vertex ABI is48 with four UV scalars");
}
}
int main(){try{StateAndLists();FeedbackAndRollback();DependencyAndGeometry();std::cout<<"PASS "<<checks<<" independent texture-unit/current/list/attribute/RTT/geometry checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
